sourcesContent:["\n$device-xs: 400px;\n$device-sm: 768px;\n$device-md: 992px;\n$device-lg: 1200px;\n\n.popup {\n    padding: 0.75rem 0 1rem;\n    font-family: system-ui, -apple-system, BlinkMacSystemFont, 'Segoe UI',\n    sans-serif;\n    color: #111827;\n}\n\n.popup-header {\n    margin-bottom: 0.75rem;\n    padding: 0.75rem 0.75rem;\n    border-radius: 0.75rem;\n    background: linear-gradient(135deg, #1f2937, #111827);\n    box-shadow: 0 6px 14px rgba(15, 23, 42, 0.35);\n}\n\n.header-icon-wrap {\n    display: flex;\n    align-items: center;\n    justify-content: center;\n}\n\n.header-icon {\n    width: 32px;\n    height: 32px;\n    border-radius: 0.75rem;\n    box-shadow: 0 4px 8px rgba(0, 0, 0, 0.35);\n}\n\n.popup-title {\n    font-size: 1.05rem;\n    margin: 0 0 0.1rem;\n    color: #f9fafb;\n}\n\n.popup-subtitle {\n    margin: 0;\n    font-size: 0.8rem;\n    color: #d1d5db;\n}\n\n/* Cards */\n\n.card {\n    background: #ffffff;\n    border-radius: 0.75rem;\n    padding: 0.75rem 0.85rem;\n    box-shadow: 0 4px 10px rgba(15, 23, 42, 0.08);\n    border: 1px solid rgba(148, 163, 184, 0.3);\n}\n\n.card + .card {\n    margin-top: 0.5rem;\n}\n\n.card-title {\n    margin: 0 0 0.35rem;\n    font-size: 0.95rem;\n    font-weight: 600;\n    color: #111827;\n}\n\n.card-text {\n    margin: 0 0 0.6rem;\n    font-size: 0.8rem;\n    color: #4b5563;\n}\n\n.card-settings {\n    margin-top: 0.5rem;\n}\n\n/* Status card */\n\n.status-card {\n    background: #0f172a;\n    border-radius: 0.75rem;\n    padding: 0.7rem 0.85rem;\n    color: #e5e7eb;\n    box-shadow: 0 4px 12px rgba(15, 23, 42, 0.4);\n    border: 1px solid #1f2937;\n    font-size: 0.8rem;\n}\n\n.status-header {\n    display: flex;\n    align-items: center;\n    gap: 0.4rem;\n    margin-bottom: 0.25rem;\n}\n\n.status-dot {\n    width: 9px;\n    height: 9px;\n    border-radius: 999px;\n    display: inline-block;\n    background: #6b7280;\n}\n\n.status-dot--idle {\n    background: #6b7280;\n}\n\n.status-dot--connecting {\n    background: #f59e0b;\n}\n\n.status-dot--connected {\n    background: #22c55e;\n}\n\n.status-dot--error {\n    background: #ef4444;\n}\n\n.status-label {\n    font-weight: 500;\n\n    &, & > * {\n        color: lightgray;\n    }\n}\n\n.status-message {\n    margin: 0;\n    color: #9ca3af;\n}\n\n/* Form / fields */\n\n.code-form {\n    margin-top: 0.4rem;\n    display: flex;\n    flex-direction: column;\n    gap: 0.5rem;\n}\n\n/* button row */\n.code-form-actions {\n    display: flex;\n    justify-content: flex-end;\n    width: 100%;\n}\n\n/* From device-md upwards: field + button side-by-side */\n@media (min-width: $device-sm) {\n    .code-form {\n        flex-direction: row;\n        align-items: center;\n        gap: 0.5rem;\n    }\n\n    .code-form .field {\n        flex: 1 1 auto;      // now it's width-based because flex-direction is row\n    }\n\n    .code-form-actions {\n        width: auto;\n        margin-top: 0;\n        justify-content: flex-start;\n    }\n}\n\n/* Field */\n\n.field {\n    display: flex;\n    flex-direction: column;\n    gap: 0.25rem;\n    max-width: 100%;\n}\n\n/* On wider screens: label + input inline */\n@media (min-width: $device-xs) {\n    .field {\n        flex-direction: row;\n        align-items: center;\n        gap: 0.5rem;\n    }\n\n    .field-label {\n        min-width: 120px;\n        white-space: nowrap;\n    }\n\n    .field-input {\n        flex: 1 1 auto;\n    }\n}\n\n.field-label {\n    font-size: 0.75rem;\n    font-weight: 500;\n    color: #4b5563;\n}\n\n.field-input {\n    border-radius: 0.5rem;\n    border: 1px solid #d1d5db;\n    padding: 0.35rem 0.5rem;\n    font-size: 0.8rem;\n    outline: none;\n    background-color: #f9fafb;\n    transition: border-color 0.15s ease, box-shadow 0.15s ease,\n    background-color 0.15s ease;\n}\n\n.field-input:focus {\n    border-color: #3b82f6;\n    background-color: #ffffff;\n    box-shadow: 0 0 0 1px rgba(59, 130, 246, 0.4);\n}\n\n.field-select {\n    padding-right: 1.6rem;\n}\n\n/* Buttons */\n\n.btn {\n    display: inline-flex;\n    align-items: center;\n    justify-content: center;\n    gap: 0.25rem;\n    border-radius: 999px;\n    border: none;\n    padding: 0.35rem 0.8rem;\n    font-size: 0.8rem;\n    font-weight: 500;\n    cursor: pointer;\n    transition: transform 0.08s ease-out, box-shadow 0.1s ease,\n    background-color 0.1s ease, opacity 0.1s ease;\n    user-select: none;\n}\n\n.btn-primary {\n    background: #2563eb;\n    color: #f9fafb;\n    box-shadow: 0 4px 10px rgba(37, 99, 235, 0.3);\n}\n\n.btn-primary:hover {\n    background: #1d4ed8;\n}\n\n.btn-secondary {\n    background: #e5e7eb;\n    color: #111827;\n}\n\n.btn-secondary:hover {\n    background: #d4d4d8;\n}\n\n.btn:active {\n    transform: translateY(1px);\n    box-shadow: 0 2px 5px rgba(15, 23, 42, 0.25);\n}\n\n/* Settings */\n\n.settings-row {\n    display: flex;\n    flex-wrap: wrap;\n    gap: 0.75rem;\n    margin-top: 0.25rem;\n}\n\n/* here we DO want flex-based width for fields */\n.settings-row .field {\n    flex: 1 1 220px;\n}\n\ncode {\n    font-family: ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas,\n    'Liberation Mono', 'Courier New', monospace;\n    font-size: 0.78rem;\n    background-color: #f3f4f6;\n    padding: 0.05rem 0.25rem;\n    border-radius: 0.25rem;\n}\n"],
